// ── 92. AI-Assisted Scouting ──────────────────────────────────────────────────
const s92: SlotSpec = {
  n: 92,
  storyType: "explainer",
  build(a) {
    const lSql = `SELECT ${YEAR()} year, SUM(d.batter_runs) * 1.0 / SUM(CASE WHEN d.is_wide = 0 THEN 1 ELSE 0 END) rpb FROM deliveries d JOIN innings i ON i.innings_id = d.innings_id JOIN matches m ON m.match_id = d.match_id WHERE ${REGULATION} GROUP BY year`;
    const lg = new Map(a.rows<{ year: number; rpb: number }>(lSql).map((r) => [r.year, r.rpb]));
    const sql = `SELECT pl.name, ${YEAR()} year, MAX(CASE WHEN i.batting_team_id IN ${a.T} THEN 1 ELSE 0 END) mine, SUM(d.batter_runs) runs, SUM(CASE WHEN d.is_wide = 0 THEN 1 ELSE 0 END) balls,
        SUM(CASE WHEN d.batter_runs IN (4, 6) THEN 1 ELSE 0 END) bnd, SUM(CASE WHEN d.is_wide = 0 AND d.batter_runs = 0 THEN 1 ELSE 0 END) dots
      FROM deliveries d JOIN innings i ON i.innings_id = d.innings_id JOIN matches m ON m.match_id = d.match_id JOIN players pl ON pl.player_id = d.batter_id WHERE ${REGULATION} GROUP BY pl.name, year`;
    const rs = a.rows<{ name: string; year: number; mine: number; runs: number; balls: number; bnd: number; dots: number }>(sql).filter((r) => r.balls >= 100);
    const idx = new Map(rs.map((r) => [`${r.name}|${r.year}`, r]));
    const rel = (r: { runs: number; balls: number; year: number }) => (r.runs / (r.balls * (lg.get(r.year) ?? 1))) * 100;
    const rows = rs.map((r) => ({ r, n: idx.get(`${r.name}|${r.year + 1}`) })).filter((x) => x.n).map(({ r, n }) => ({ year: r.year, mine: r.mine, x: [1, rel(r), (r.bnd / r.balls) * 100, (r.dots / r.balls) * 100, Math.log(r.balls)], y: rel(n!) }));
    const train = rows.filter((r) => r.year <= 2019), test = rows.filter((r) => r.year >= 2020);
    const p = 5, XtX = Array.from({ length: p }, () => new Array(p).fill(0)), Xty = new Array(p).fill(0);
    for (const r of train) for (let i = 0; i < p; i++) { Xty[i] += r.x[i] * r.y; for (let j = 0; j < p; j++) XtX[i][j] += r.x[i] * r.x[j]; }
    for (let i = 1; i < p; i++) XtX[i][i] += 1e-6;
    const beta = solve(XtX, Xty);
    const ybar = mean(train.map((r) => r.y));
    const mae = (f: (r: (typeof rows)[number]) => number) => mean(test.map((r) => Math.abs(f(r) - r.y)));
    const mModel = mae((r) => r.x.reduce((s, v, i) => s + v * beta[i], 0)), mPers = mae((r) => r.x[1]), mMean = mae(() => ybar);
    a.table("ai-cmp", "Predicting next-season relative strike rate, 2020–2025 test seasons", "Mean absolute error, index points (100 = season average); trained on 2008–2019", test.length, "batter-season pairs", sql, [
      { method: "League average", mae: dp(mMean, 1) }, { method: "Same as last season", mae: dp(mPers, 1) }, { method: "Four-feature model", mae: dp(mModel, 1) },
    ]);
    const tok = {
      train: a.int("ai-train", train.length, "Training pairs (seasons up to 2019)", { filters: "Batters with 100+ balls in consecutive seasons", n: train.length, nUnit: "pairs", sql, check: floor(train.length, 100, "pairs") }),
      test: a.int("ai-test", test.length, "Test pairs (seasons from 2020)", { filters: "As above", n: test.length, nUnit: "pairs", sql, check: floor(test.length, 50, "pairs") }),
      model: a.num("ai-model", mModel, "Model's mean absolute error", { unit: "index points", filters: "Test pairs", n: test.length, nUnit: "pairs", sql, check: range(mModel, 0, 60, "error") }, 1),
      pers: a.num("ai-pers", mPers, "Error when predicting the same as last season", { unit: "index points", filters: "Test pairs", n: test.length, nUnit: "pairs", sql, check: range(mPers, 0, 60, "error") }, 1),
      mean: a.num("ai-mean", mMean, "Error when predicting the league average", { unit: "index points", filters: "Test pairs", n: test.length, nUnit: "pairs", sql, check: range(mMean, 0, 60, "error") }, 1),
    };
    const beats = mModel < Math.min(mPers, mMean) - 0.5;
    return {
      dek: `Where could algorithms genuinely help ${a.name} recruit? A small, honest model shows how much of next season's batting can be predicted, and how much cannot.`,
      excerpt: `Trained on IPL seasons up to 2019 and tested on later ones, a four-feature model predicts next season's relative strike rate ${beats ? "better than" : "no better than"} simple rules of thumb. Its errors are the real lesson for AI-assisted scouting.`,
      keyTakeaways: [
        `Tested on ${tok.test} batter-season pairs since 2020, the model's average error was ${tok.model} index points.`,
        `Predicting the same as last season erred by ${tok.pers}; predicting the league average by ${tok.mean}.`,
        beats ? `The model beats both rules of thumb, but most of the variation in next season's form remains unpredictable.` : `The model does not clearly beat simple rules, which shows how much of next season's form is unpredictable.`,
      ],
      sections: [
        { heading: "What an Algorithm Can Do", body: [
          `AI-assisted scouting promises to find patterns humans miss. The honest first question is how predictable player performance actually is.`,
          `CricField trained a small model on ${tok.train} batter-season pairs up to 2019, using four features of one season (relative strike rate, boundary rate, dot-ball rate and balls faced) to predict the next season's relative strike rate.`,
        ] },
        { heading: "How It Did", body: [
          `On ${tok.test} pairs from 2020 onwards, the model's average error was ${tok.model} index points. Predicting the same as last season erred by ${tok.pers}, and predicting the league average by ${tok.mean}.`,
          `The chart compares the three.`,
        ], chartIds: ["ai-chart"] },
        { heading: "Where Algorithms Help", body: [
          `Even a modest edge helps when applied across hundreds of candidates: models are good at screening and at correcting for small samples, venue and era. They are weak at role fit, temperament and injury risk.`,
          `{{hyp:ai}}`,
        ] },
        { heading: "What This Model Is Not", body: [
          `It is deliberately simple and uses IPL data only. Richer inputs, such as ball-tracking, domestic cricket and other leagues, would improve it, at the cost of transparency.`,
          `Any production model should report its error against these baselines.`,
        ] },
        { heading: "CricField Verdict: Use Models to Screen, People to Decide", body: [
          `${a.name} should use algorithms to screen and rank candidates and to flag small-sample traps, and leave final decisions to scouts who can judge role and character.`,
          `The model's error is the measure of how much human judgement is still needed.`,
        ] },
      ],
      charts: [{ id: "ai-chart", type: "column", title: "Prediction error by method", subtitle: "Next-season relative strike rate, test seasons 2020–2025", table: "ai-cmp", xKey: "method", series: [{ key: "mae", label: "Mean absolute error" }], xLabel: "Method", unit: "index points", takeaway: beats ? "The model edges out simple rules, but errors stay large." : "Simple rules do about as well as the model.", ariaLabel: "Column chart of mean absolute prediction error for three methods of forecasting next-season batting." }],
      hypotheses: [hyp("ai", "adding batting position and phase mix as features reduces the model's error more than adding any single performance statistic.", "Those features have not been added.", "Retrain with position and phase-mix features and compare test error.")],
      literalNumbers: [{ text: "100", reason: "Index baseline and minimum balls." }],
      players: [],
      seasons: ["2008–2026"],
      hero: { narrative: `${a.name} scouting the next star.`, wanted: `${a.name} young batter.`, query: `${a.name} batter` },
      related: [80, 84, 99],
      seo: { metaTitle: metaTitle(`AI-assisted scouting: where algorithms could help ${a.code}`), metaDescription: metaDesc(`A transparent model of next-season batting, tested against simple rules, and what it means for ${a.poss} recruitment.`) },
      methodology: `${METHOD} Ordinary least squares on relative strike rate, boundary rate, dot-ball rate and log balls; trained on seasons up to 2019, tested on 2020–2025.`,
    };
  },
};

